    /// <summary>读取老爹战斗说明，未知键保留原值以便定位遗漏。</summary>
    private static string GetGrandMageText(string key, bool chinese)
        => GrandMageTexts.TryGetValue(key[9..], out var text) ? chinese ? text.Chinese : text.English : key;
}
